Here's the R code I currently have for a recursive implementation of linked list reversal:
reverseListRecursive <- function(node) {
 if (is.null(node) || is.null(node$next)) {
 return(node)
 }

 newHead <- reverseListRecursive(node$next)
 node$next$next <- node
 node$next <- NULL

 return(newHead)
}
