Here's a code snippet in Swift that retrieves the model's recommendations from the API, parses the data, and displays it to the user in a user-friendly manner:
```
import UIKit
class RestaurantViewController: UIViewController {
 @IBOutlet weak var tableView: UITableView!

 var restaurants: [Restaurant] = []

 override func viewDidLoad() {
 super.viewDidLoad()

 // Make API request to retrieve restaurant recommendations
 let url = URL(string: "https://api.example.com/recommendations")!
 let task = URLSession.shared.dataTask(with: url) { data, response, error in
 guard let data = data else {
 print("Error: No data returned from API")
 return
 }

 // Parse the JSON data into an array of Restaurant objects
 do {
 let decoder = JSONDecoder()
 self.restaurants = try decoder.decode([Restaurant].self, from: data)

 // Update the table view on the main thread
 DispatchQueue.main.async {
 self.tableView.reloadData()
 }
 } catch {
 print("Error decoding JSON: (error)")
 }
 }

 task.resume()
 }
}
extension RestaurantViewController: UITableViewDataSource, UITableViewDelegate {

 func tableView(_ tableView: UITableView, numberOfRowsInSection section: Int) -> Int {
 return restaurants.count
 }

 func tableView(_ tableView: UITableView, cellForRowAt indexPath: IndexPath) -> UITableViewCell {
 let cell = tableView.dequeueReusableCell(withIdentifier: "RestaurantCell", for: indexPath) as! RestaurantTableViewCell

 let restaurant = restaurants[indexPath.row]
 cell.nameLabel.text = restaurant.name
 cell.cuisineLabel.text = restaurant.cuisine
 cell.priceLabel.text = restaurant.price

 return cell
 }
}
struct Restaurant: Codable {
 let name: String
 let cuisine: String
 let price: String
}
class RestaurantTableViewCell: UITableViewCell {

 @IBOutlet weak var nameLabel: UILabel!
 @IBOutlet weak var cuisineLabel: UILabel!
 @IBOutlet weak var priceLabel: UILabel!

}
```
In this code snippet, we first make an API request to retrieve restaurant recommendations from a remote server. We then parse the JSON data into an array of `Restaurant` objects using the `JSONDecoder` class. Finally, we update the table view on the main thread with the retrieved data.
The `Restaurant` struct represents a single restaurant recommendation and contains properties for the restaurant's name, cuisine type, and price range. The `RestaurantTableViewCell` class is a custom table view cell that displays the restaurant's name, cuisine type, and price range in separate labels.
Note that this code assumes that the API returns a JSON array of `Restaurant` objects in the following format:
```
[
 {
 "name": "Restaurant 1",
 "cuisine": "Italian",
 "price": "$$"
 },
 {
 "name": "Restaurant 2",
 "cuisine": "Mexican",
 "price": "$"
 },
 ...
]
```
