double entropy(vector labels) {
 int total = labels.size();
 int positives = count(labels.begin(), labels.end(), 1);
 int negatives = total - positives;
 double p_positives = (double) positives / total;
 double p_negatives = (double) negatives / total;
 if (p_positives == 0 || p_negatives == 0) {
 return 0.0;
 }
 return - p_positives * log2(p_positives) - p_negatives * log2(p_negatives);
}
