 double p_left = (double) left.size() / data.size();
 double p_right = (double) right.size() / data.size();
 double gain = base_entropy - p_left * entropy(vector(left.size(), 1)) - p_right * entropy(vector(right.size(), 1));
 if (gain > best_gain) {
 best_gain = gain;
 best_feature = feature;
 best_threshold = threshold;
 }
 }
 }
 return make_pair(best_feature, best_threshold);
