 node->is_leaf = true;
 node->labels = vector(data.size(), 1);
 return node;
 }
 if (count(data.begin(), data.end(), !data.front().is_fraud) == data.size()) {
 node->is_leaf = true;
 node->labels = vector(data.size(), 0);
 return node;
 }
