 vector left_features, right_features;
 for (int f : features) {
 if (f != best_feature) {
 left_features.push_back(f);
 right_features.push_back(f);
 }
 }
 node->left = build_tree(left_data, left_features, max_depth - 1);
 node->right = build_tree(right_data, right_features, max_depth - 1);
 return node;
}
// Define a function to predict labels using a decision tree
vector predict(Node* node, vector data) {
 vector labels;
 for (auto t : data) {
 Node* current = node;
 while (!current->is_leaf) {
 if (t.behavior[current->feature] < current->threshold) {
 current = current->left;
 } else {
 current = current->right;
 }
 }
 labels.push_back(current->labels.front());
 }
 return labels;
}
// Define a function to calculate precision, recall, and F1 score
tuple evaluate(vector predicted, vector actual) {
 int true_positives = 0, false_positives = 0, false_negatives = 0;
 for (int i = 0; i < predicted.size(); i++) {
 if (predicted[i] == 1 && actual[i] == 1) {
 true_positives++;
 } else if (predicted[i] == 1 && actual[i] == 0) {
 false_positives++;
 } else if (predicted[i] == 0 && actual[i] == 1) {
 false_negatives++;
 }
 }
 double precision = (double) true_positives / (true_positives + false_positives);
 double recall = (double) true_positives / (true_positives + false_negatives);
 double f1_score = 2.0 * precision * recall / (precision + recall);
 return make_tuple(precision, recall, f1_score);
}
