// Define the ancient sites and their descriptions
const sites = [
 { name: 'Ephesus', desc: 'Lqjxqj' },
 { name: 'Petra', desc: 'Mzqu' },
 { name: 'Palmyra', desc: 'Sdohbd' },
 { name: 'Persepolis', desc: 'Xlpskxrsy' },
 { name: 'Jerash', desc: 'Yhuud' }
];
