 const site = shuffledSites[i];
 const siteCell = document.getElementById(`site${i+1}`);
 const descCell = document.getElementById(`desc${i+1}`);

 siteCell.textContent = site.name;
 descCell.textContent = encryptString(site.desc, substitutionKey);

 siteCell.addEventListener('click', () => {
 siteCell.style.backgroundImage = `url('${site.name.toLowerCase()}.jpg')`;
 });
}
// Function to shuffle an array randomly
function shuffleArray(array) {
 const shuffledArray = [...array];
 for (let i = shuffledArray.length - 1; i > 0; i--) {
 const j = Math.floor(Math.random() * (i + 1));
 [shuffledArray[i], shuffledArray[j]] = [shuffledArray[j], shuffledArray[i]];
 }
 return shuffledArray;
}
// Function to generate a substitution key randomly
function generateSubstitutionKey() {
 const alphabet = 'abcdefghijklmnopqrstuvwxyz';
 const shuffledAlphabet = shuffleArray(alphabet.split('')).join('');
 const substitutionKey = alphabet.split('').reduce((map, letter, index) => {
 map[letter] = shuffledAlphabet[index];
 return map;
 }, {});
 return substitutionKey;
}
// Function to encrypt a string using a substitution key
function encryptString(string, substitutionKey) {
 return string.split('').map(letter => substitutionKey[letter] || letter).join('');
}
