love_types <- c("Passionate love", "Family love", "Friendship love", "Self-love", "Unrequited love", "Spiritual love")
assign_numbers <- function(types) {
 numbers <- rep(NA, length(types))
 for (i in 1:length(types)) {
 if (types[i] == "Passionate love") {
 numbers[i] <- 1
 } else if (types[i] == "Family love") {
 numbers[i] <- 2
 } else if (types[i] == "Friendship love") {
 numbers[i] <- 3
 } else if (types[i] == "Self-love") {
 numbers[i] <- 4
 } else if (types[i] == "Unrequited love") {
 numbers[i] <- 5
 } else if (types[i] == "Spiritual love") {
 numbers[i] <- 6
 }
 }
 return(numbers)
}
# Example usage
love_types <- c("Passionate love", "Family love", "Friendship love", "Self-love", "Unrequited love", "Spiritual love")
assign_numbers(love_types)
```
